const PATCH_KEY='arseia-patch-seen';
function patchHtml(all){const list=all?PATCHES:PATCHES.slice(0,1);
  return list.map(p=>`<div class="pnote"><div class="ph"><b>v${p.v}</b> ${p.t} <span class="muted">${p.d}</span></div><ul>${p.items.map(i=>`<li>${i}</li>`).join('')}</ul></div>`).join('')}
function patchOpen(all){let el=$('#patch');if(!el){el=document.createElement('div');el.id='patch';document.body.appendChild(el);
    el.addEventListener('click',e=>{if(e.target===el||e.target.closest('[data-pclose]'))patchClose();else if(e.target.closest('[data-pall]'))patchOpen(true)})}
  el.innerHTML=`<div class="card"><h2 style="margin-top:0">${all?'패치노트':'새 버전 v'+PATCHES[0].v}</h2>${patchHtml(all)}<div class="acts">${all?'':'<button type="button" data-pall="1">지난 패치노트 보기</button>'}<button type="button" data-pclose="1">확인</button></div></div>`;
  el.hidden=false;try{localStorage.setItem(PATCH_KEY,String(PATCHES[0].v))}catch(_){}}
function patchClose(){const el=$('#patch');if(el)el.hidden=true}
addEventListener('keydown',e=>{const el=$('#patch');if(el&&!el.hidden&&(e.code==='Escape'||e.code==='Enter')){e.preventDefault();e.stopImmediatePropagation();patchClose()}},true);
{const b=document.createElement('button');b.className='stonebox';b.id='patchBtn';b.type='button';b.textContent='패치노트';b.onclick=()=>patchOpen(true);
  const tools=document.querySelector('.tools');if(tools)tools.appendChild(b)}
// 시작 화면: 최신 요약 한 줄 + 처음 보는 버전이면 바로 띄움
{const card=document.querySelector('#intro .card');if(card){const d=document.createElement('div');d.className='pnew';
    d.innerHTML=`<b>v${PATCHES[0].v}</b> ${PATCHES[0].t} <button type="button" id="patchIntro">패치노트</button>`;
    card.insertBefore(d,card.querySelector('#introBody'));d.querySelector('button').onclick=()=>patchOpen(true)}
  let seen=null;try{seen=localStorage.getItem(PATCH_KEY)}catch(_){}
  if(seen!==String(PATCHES[0].v)&&!/#gallery/.test(location.hash)&&!navigator.webdriver)setTimeout(()=>patchOpen(false),300)}
